FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR

VAR_OUTPUT
    elementCount : DINT;
    status       : WORD;
END_VAR

VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR

VAR
    head        : DINT := 1;
    tail        : DINT := 1;
    enqueueOld  : BOOL := FALSE;
    dequeueOld  : BOOL := FALSE;
END_VAR

VAR
    enqueueRising : BOOL;
    dequeueRising : BOOL;
END_VAR

// Detect rising edges
enqueueRising := enqueue AND NOT enqueueOld;
dequeueRising := dequeue AND NOT dequeueOld;

// Reset takes priority
IF reset THEN
    elementCount := 0;
    head := 1;
    tail := 1;
    status := 16#0000;

// Enqueue on rising edge
ELSIF enqueueRising THEN
    IF elementCount < capacity THEN
        buffer[tail] := item;
        tail := (tail MOD capacity) + 1;
        elementCount := elementCount + 1;
        status := 16#0000;
    ELSE
        status := 16#8002;
    END_IF;

// Dequeue on rising edge
ELSIF dequeueRising THEN
    IF elementCount > 0 THEN
        item := buffer[head];
        head := (head MOD capacity) + 1;
        elementCount := elementCount - 1;
        status := 16#0000;
    ELSE
        status := 16#8001;
    END_IF;

// Idle
ELSE
    status := 16#0000;
END_IF;

// Update edge detection history
enqueueOld := enqueue;
dequeueOld := dequeue;

END_FUNCTION_BLOCK
